class Center {
  + name : string
  + address : string
}

class Room {
  + roomNumber : int
  + maxCapacity : int
}

abstract class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Member {
}

class Trainer {
  + diploma : string
}

class Prospect {
}

class Intern {
}

class Session {
  + date : date
  + startHour : time
}

class IndividualSession {
}

class GroupSession {
  + type : string
}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

Person "1" -- "0..*" Member
Person "1" -- "0..*" Trainer
Person "1" -- "0..*" Prospect
Person "1" -- "0..*" Intern

Trainer --|> Person
Member --|> Person
Prospect --|> Person
Intern --|> Person

Session --|> IndividualSession
Session --|> GroupSession

GroupSession "1" -- "1" Trainer
IndividualSession "0..*" -- "0..*" Member
GroupSession "0..*" -- "0..*" Member

@enduml

